CREATE TYPE public.inventra_role AS ENUM ('head','manager','warehouse','supplier');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.inventra_workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL DEFAULT 'My business', owner_id uuid NOT NULL, data jsonb NOT NULL DEFAULT '{"P":[],"archived":[],"SR":[],"mv":[],"R":[],"N":[],"imports":[],"settings":{"currency":"USD"},"snooze":{},"watch":[],"alerts":[],"px":{},"nid":1,"rid":1}', recovery jsonb, version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.inventra_workspaces TO authenticated; GRANT ALL ON public.inventra_workspaces TO service_role;
ALTER TABLE public.inventra_workspaces ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, workspace_id uuid NOT NULL REFERENCES public.inventra_workspaces(id) ON DELETE CASCADE, role public.inventra_role NOT NULL, UNIQUE(user_id,workspace_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.inventra_member(w uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE workspace_id=w AND user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.inventra_member(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.inventra_member(uuid) TO authenticated;
CREATE POLICY workspace_read ON public.inventra_workspaces FOR SELECT TO authenticated USING(public.inventra_member(id));
CREATE FUNCTION public.inventra_profile_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END $$;
CREATE TRIGGER inventra_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.inventra_profile_signup();
CREATE FUNCTION public.inventra_create_workspace() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; SELECT workspace_id INTO w FROM public.user_roles WHERE user_id=auth.uid() LIMIT 1; IF w IS NOT NULL THEN RETURN w; END IF; INSERT INTO public.inventra_workspaces(owner_id) VALUES(auth.uid()) RETURNING id INTO w; INSERT INTO public.user_roles(user_id,workspace_id,role) VALUES(auth.uid(),w,'head'); RETURN w; END $$;
REVOKE ALL ON FUNCTION public.inventra_create_workspace() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.inventra_create_workspace() TO authenticated;
CREATE FUNCTION public.inventra_save_workspace(w uuid, expected_version integer, next_data jsonb, keep_recovery boolean DEFAULT false) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v integer; BEGIN IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND workspace_id=w AND role IN ('head','manager')) THEN RAISE EXCEPTION 'Only the business owner and managers can change data'; END IF; IF jsonb_typeof(next_data->'P') IS DISTINCT FROM 'array' OR jsonb_typeof(next_data->'SR') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid workspace data'; END IF; UPDATE public.inventra_workspaces SET recovery=CASE WHEN keep_recovery THEN data ELSE recovery END, data=next_data,version=version+1,updated_at=now() WHERE id=w AND version=expected_version RETURNING version INTO v; IF v IS NULL THEN RAISE EXCEPTION 'This workspace changed in another session. Refresh before trying again.'; END IF; RETURN v; END $$;
REVOKE ALL ON FUNCTION public.inventra_save_workspace(uuid,integer,jsonb,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.inventra_save_workspace(uuid,integer,jsonb,boolean) TO authenticated;
CREATE TABLE public.inventra_invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.inventra_workspaces(id) ON DELETE CASCADE, token uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(), email text NOT NULL, role public.inventra_role NOT NULL, expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', accepted_at timestamptz);
GRANT SELECT ON public.inventra_invites TO authenticated; GRANT ALL ON public.inventra_invites TO service_role;
ALTER TABLE public.inventra_invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY invite_owner_read ON public.inventra_invites FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND workspace_id=inventra_invites.workspace_id AND role='head'));
CREATE FUNCTION public.inventra_invite(w uuid, invite_email text, invite_role public.inventra_role) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t uuid; BEGIN IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND workspace_id=w AND role='head') THEN RAISE EXCEPTION 'Only the owner can invite team members'; END IF; IF invite_role='head' OR position('@' in invite_email)=0 THEN RAISE EXCEPTION 'Invalid invitation'; END IF; INSERT INTO public.inventra_invites(workspace_id,email,role) VALUES(w,lower(trim(invite_email)),invite_role) RETURNING token INTO t; RETURN t; END $$;
REVOKE ALL ON FUNCTION public.inventra_invite(uuid,text,public.inventra_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.inventra_invite(uuid,text,public.inventra_role) TO authenticated;
CREATE FUNCTION public.inventra_accept_invite(invite_token uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.inventra_invites; BEGIN SELECT * INTO i FROM public.inventra_invites WHERE token=invite_token AND accepted_at IS NULL AND expires_at>now() FOR UPDATE; IF i.id IS NULL OR lower(coalesce(auth.jwt()->>'email',''))<>i.email THEN RAISE EXCEPTION 'This invitation is expired or belongs to another email address'; END IF; INSERT INTO public.user_roles(user_id,workspace_id,role) VALUES(auth.uid(),i.workspace_id,i.role) ON CONFLICT(user_id,workspace_id) DO UPDATE SET role=EXCLUDED.role; UPDATE public.inventra_invites SET accepted_at=now() WHERE id=i.id; RETURN i.workspace_id; END $$;
REVOKE ALL ON FUNCTION public.inventra_accept_invite(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.inventra_accept_invite(uuid) TO authenticated;